import { registerWebComponents } from '@domg-wc/common';
import { VlTitleComponent } from '@domg-wc/components/atom';
import { VlProzaMessage, VlProzaMessagePreloader } from '@domg-wc/components/block';
import { VlSideNavigationLayoutComponent } from '@domg-wc/components/block/next';

registerWebComponents([VlSideNavigationLayoutComponent, VlProzaMessagePreloader, VlProzaMessage, VlTitleComponent]);

// Enkel voor de demo: Storybook heeft geen Proza-backend. De story zet de berichten van het domein daarom zelf in de
// cache, vlak voor ze de HTML rendert. In een toepassing laat je dit weg: vl-proza-message-preloader haalt de
// berichten op van proza/domein/{domain}, relatief tov de huidige url of achter base-url.
const domain = 'side-navigation-layout-proza-message';

VlProzaMessagePreloader.__setPreloadedMessagesCacheForDomain(
    domain,
    Promise.resolve({
        'page-title': 'Side navigation layout met proza message',
        'section-1-title': 'Ontwerpprincipes',
        'section-1-sub-1': 'Consistente headings',
        'section-1-sub-2': 'Scanbare content',
        'section-1-sub-3': 'Toegankelijkheid',
        'section-2-title': 'Implementatie',
        'section-2-sub-1': 'Preloaden van berichten',
        'section-2-sub-2': 'Vullen van titels',
        'section-2-sub-3': 'Validatie',
        'section-3-title': 'Resultaat',
        'section-3-sub-1': 'Wat je in de side navigation ziet',
        'section-3-sub-2': 'Samenvatting',
    })
);

// Zonder de operatie update toont vl-proza-message geen knoppen om een bericht te bewerken of te herladen. Zonder
// deze regel vraagt vl-proza-message de toegelaten operaties op bij proza/domein/{domain}/toegelatenoperaties.
VlProzaMessage.__setToegelatenOperatiesCacheForDomain(domain, Promise.resolve({ update: false }));
